import { describe, expect, it } from 'vitest';
import { reportView } from './Solution';

/**
 * 断言由 gen.py 里同一个 Python 模型生成，不手抄 ——
 * react-vitest 题的判分事实来源就是这份文件，抄错一次就永久错一次。
 * 契约型用例断言到**消息**：只写 .toThrow() 会让几条"都该抛错"的用例收敛成同一条。
 */
describe('reportView：实验报告结论区读数口径', () => {
  it("基线：累计去重 + 比例均衡 + 已达显著 ⇒ 可提交放行评审", () => {
    expect(reportView({"daysRunning": 3, "expectedSplitBps": 5000, "actualSplitBps": 5000, "samplePerGroup": 20000, "updatedT1": true, "denominator": "cumulative-dedup", "significant": true, "liftBps": 410})).toEqual({"splitDeviationBps": 0, "blockers": [], "verdict": "ship-candidate", "tone": "ok", "headline": "可提交放行评审", "canPublish": true, "liftBps": 410});
  });
  it("官方口径：进组 48.7% vs 预设 50% ⇒ 相对偏离 260 万分比，未越 1000 线", () => {
    expect(reportView({"daysRunning": 3, "expectedSplitBps": 5000, "actualSplitBps": 4870, "samplePerGroup": 20000, "updatedT1": true, "denominator": "cumulative-dedup", "significant": true, "liftBps": 410})).toEqual({"splitDeviationBps": 260, "blockers": [], "verdict": "ship-candidate", "tone": "ok", "headline": "可提交放行评审", "canPublish": true, "liftBps": 410});
  });
  it("SRM 优先于一切解释：偏离超过 10% 就直接判废", () => {
    expect(reportView({"daysRunning": 3, "expectedSplitBps": 5000, "actualSplitBps": 4400, "samplePerGroup": 20000, "updatedT1": true, "denominator": "cumulative-dedup", "significant": true, "liftBps": 900})).toEqual({"splitDeviationBps": 1200, "blockers": ["SRM"], "verdict": "invalid", "tone": "danger", "headline": "进组比例偏离预设 12.00%，结论不成立", "canPublish": false, "liftBps": 900});
  });
  it("分母换成就\"显著\"了 ⇒ 先降级成 hold，不去解释业务", () => {
    expect(reportView({"daysRunning": 3, "expectedSplitBps": 5000, "actualSplitBps": 5000, "samplePerGroup": 20000, "updatedT1": true, "denominator": "daily-active", "significant": true, "liftBps": 410})).toEqual({"splitDeviationBps": 0, "blockers": ["DENOMINATOR"], "verdict": "hold", "tone": "warn", "headline": "分母口径不是累计去重进组用户，先换回官方口径再判", "canPublish": false, "liftBps": 410});
  });
  it("边界：实验已开到第 4 天但数据没按 T-1 更新 ⇒ 今天的数不是结论", () => {
    expect(reportView({"daysRunning": 4, "expectedSplitBps": 5000, "actualSplitBps": 5000, "samplePerGroup": 20000, "updatedT1": false, "denominator": "cumulative-dedup", "significant": true, "liftBps": 410})).toEqual({"splitDeviationBps": 0, "blockers": ["STALE"], "verdict": "hold", "tone": "warn", "headline": "数据未按 T-1 更新，今天的数字还不是结论", "canPublish": false, "liftBps": 410});
  });
  it("退化：实验第 1 天尚未 T-1（官方口径：开启当天按实时统计）⇒ 不算 STALE", () => {
    expect(reportView({"daysRunning": 1, "expectedSplitBps": 5000, "actualSplitBps": 5000, "samplePerGroup": 20000, "updatedT1": false, "denominator": "cumulative-dedup", "significant": true, "liftBps": 410})).toEqual({"splitDeviationBps": 0, "blockers": [], "verdict": "ship-candidate", "tone": "ok", "headline": "可提交放行评审", "canPublish": true, "liftBps": 410});
  });
  it("显著但样本不足 ⇒ watch：能看不能放", () => {
    expect(reportView({"daysRunning": 3, "expectedSplitBps": 5000, "actualSplitBps": 5000, "samplePerGroup": 999, "updatedT1": true, "denominator": "cumulative-dedup", "significant": true, "liftBps": 410})).toEqual({"splitDeviationBps": 0, "blockers": ["LOW-SAMPLE"], "verdict": "watch", "tone": "warn", "headline": "显著但样本偏少，只做观察不做放行", "canPublish": false, "liftBps": 410});
  });
  it("边界：样本数恰好等于 1000 ⇒ 不再算 LOW-SAMPLE", () => {
    expect(reportView({"daysRunning": 3, "expectedSplitBps": 5000, "actualSplitBps": 5000, "samplePerGroup": 1000, "updatedT1": true, "denominator": "cumulative-dedup", "significant": true, "liftBps": 410})).toEqual({"splitDeviationBps": 0, "blockers": [], "verdict": "ship-candidate", "tone": "ok", "headline": "可提交放行评审", "canPublish": true, "liftBps": 410});
  });
  it("未达显著时不报 blockers 之外的坏消息（blockers 仍要如实列出）", () => {
    expect(reportView({"daysRunning": 3, "expectedSplitBps": 5000, "actualSplitBps": 5000, "samplePerGroup": 500, "updatedT1": true, "denominator": "cumulative-dedup", "significant": false, "liftBps": 410})).toEqual({"splitDeviationBps": 0, "blockers": ["LOW-SAMPLE"], "verdict": "not-significant", "tone": "muted", "headline": "未达显著，按预注册时长继续或加样本", "canPublish": false, "liftBps": 410});
  });
  it("非法：整份入参是 null", () => {
    expect(() => reportView(null)).toThrow("input must be an object");
  });
  it("非法：未知分母口径", () => {
    expect(() => reportView({"daysRunning": 3, "expectedSplitBps": 5000, "actualSplitBps": 5000, "samplePerGroup": 20000, "updatedT1": true, "denominator": "all-users", "significant": true, "liftBps": 410})).toThrow("unknown denominator");
  });
  it("非法：预设分流比例越界", () => {
    expect(() => reportView({"daysRunning": 3, "expectedSplitBps": 0, "actualSplitBps": 5000, "samplePerGroup": 20000, "updatedT1": true, "denominator": "cumulative-dedup", "significant": true, "liftBps": 410})).toThrow("expectedSplitBps out of range");
  });
  it("非法：实际占比是负数", () => {
    expect(() => reportView({"daysRunning": 3, "expectedSplitBps": 5000, "actualSplitBps": -1, "samplePerGroup": 20000, "updatedT1": true, "denominator": "cumulative-dedup", "significant": true, "liftBps": 410})).toThrow("actualSplitBps out of range");
  });
});

